/* SANDOW V46 — original Sandow GLB, automatic WebGL rotation.
 * Uses original glTF bronze material factors, fitted orbit camera, offline mesh bytes.
 * No new geometry, no recolouring of the uploaded model.
 */
(()=>{'use strict';
const canvas=document.getElementById('heroModel');
const stage=document.getElementById('heroSculpture');
const poster=document.getElementById('sandow-reference');
const toggle=document.getElementById('statueMode');
const loading=document.getElementById('sandow3d-loading');
if(!canvas||!stage)return;
const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
const gl=canvas.getContext('webgl2',{alpha:true,antialias:true,premultipliedAlpha:false,preserveDrawingBuffer:false,powerPreference:'high-performance'});
function fallback(reason){stage.classList.remove('webgl-hero');stage.dataset.webgl='fallback';if(loading)loading.hidden=true;if(toggle){toggle.textContent='3D недоступно · показано изображение';toggle.disabled=true;}if(reason)console.warn('Sandow 3D fallback:',reason);}
if(!gl){fallback('WebGL2 is unavailable');return;}
const VS=`#version 300 es
precision highp float;
layout(location=0) in vec3 aPosition;
layout(location=1) in vec3 aNormal;
uniform float uAngle;
uniform float uCameraDistance;
uniform float uCenterY;
uniform float uAspect;
uniform float uFocal;
out vec3 vNormal;
out vec3 vEye;
out vec3 vPosition;
void main(){
 float c=cos(uAngle),s=sin(uAngle);
 vec3 pos=vec3(c*aPosition.x+s*aPosition.z,aPosition.y,-s*aPosition.x+c*aPosition.z);
 vec3 normal=vec3(c*aNormal.x+s*aNormal.z,aNormal.y,-s*aNormal.x+c*aNormal.z);
 vec3 q=pos-vec3(0.,uCenterY,0.);
 float z=uCameraDistance-q.z;
 float near=.10,far=90.;
 gl_Position=vec4(q.x*uFocal/uAspect,q.y*uFocal,(z*(far+near)-2.*far*near)/(far-near),z);
 vNormal=normalize(normal);
 vEye=normalize(vec3(-q.x,-q.y,uCameraDistance-q.z));
 vPosition=pos;
}`;
const FS=`#version 300 es
precision highp float;
in vec3 vNormal;
in vec3 vEye;
in vec3 vPosition;
uniform vec3 uBase;
uniform float uRoughness;
out vec4 colorOut;
void main(){
 vec3 n=normalize(vNormal),v=normalize(vEye);
 // A studio light environment with a neutral primary key and broad reflected panels.
 vec3 l1=normalize(vec3(-.70,.88,.76));
 vec3 l2=normalize(vec3(.90,.44,.42));
 vec3 l3=normalize(vec3(-.22,.75,-.90));
 float d1=max(dot(n,l1),0.);
 float d2=max(dot(n,l2),0.);
 float d3=max(dot(n,l3),0.);
 float soft=0.31+0.34*d1+0.18*d2+0.07*d3;
 float shininess=mix(118.,28.,clamp(uRoughness,0.,1.));
 vec3 h1=normalize(l1+v),h2=normalize(l2+v),h3=normalize(l3+v);
 float s1=pow(max(dot(n,h1),0.),shininess*.36);
 float s2=pow(max(dot(n,h2),0.),shininess*.92);
 float s3=pow(max(dot(n,h3),0.),shininess*1.40);
 float rim=pow(1.-max(dot(n,v),0.),3.5);
 vec3 base=uBase;
 vec3 col=base*soft;
 // Pure metal specular response: highlight colours are derived from glTF baseColorFactor.
 col+=base*(.85*s1+1.70*s2+.72*s3);
 col+=base*(.18*rim);
 // Dark copper body + bright metallic light strips, while preserving original
 // glTF colour factor for both sculpture and pedestal.
 col*=vec3(1.0,.84,.85);
 col=pow(clamp(col,vec3(0.),vec3(1.)),vec3(.96));
 colorOut=vec4(col,1.);
}`;
const compile=(type,code)=>{const sh=gl.createShader(type);gl.shaderSource(sh,code);gl.compileShader(sh);if(!gl.getShaderParameter(sh,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(sh)||'Shader failed');return sh;};
let program,models=[],positionArrays=[],globalBounds={min:[Infinity,Infinity,Infinity],max:[-Infinity,-Infinity,-Infinity]};
try{
 program=gl.createProgram();
 gl.attachShader(program,compile(gl.VERTEX_SHADER,VS));
 gl.attachShader(program,compile(gl.FRAGMENT_SHADER,FS));
 gl.linkProgram(program);
 if(!gl.getProgramParameter(program,gl.LINK_STATUS))throw Error(gl.getProgramInfoLog(program)||'Program failed');
 const binary=atob('');
 const ab=new ArrayBuffer(binary.length),u8=new Uint8Array(ab);
 for(let i=0;i<binary.length;i++)u8[i]=binary.charCodeAt(i);
 const dv=new DataView(ab);
 if(dv.getUint32(0,true)!==0x46546c67)throw Error('Invalid original GLB');
 const jsonLength=dv.getUint32(12,true);
 const model=JSON.parse(new TextDecoder().decode(new Uint8Array(ab,20,jsonLength)));
 const binOffset=20+jsonLength+8;
 function accessor(id){
  const a=model.accessors[id],view=model.bufferViews[a.bufferView];
  const offset=binOffset+(view.byteOffset||0)+(a.byteOffset||0);
  const sz=a.type==='VEC3'?3:1;
  if(a.componentType===5125)return new Uint32Array(ab,offset,a.count*sz).slice();
  if(a.componentType===5123)return new Uint16Array(ab,offset,a.count*sz).slice();
  if(a.componentType===5126)return new Float32Array(ab,offset,a.count*sz).slice();
  throw Error('Unsupported glTF accessor type');
 }
 for(const mesh of model.meshes){for(const prim of mesh.primitives){
  const positions=accessor(prim.attributes.POSITION),indices=accessor(prim.indices);
  positionArrays.push(positions);
  const normals=new Float32Array(positions.length);
  // GLB contains positions and indices, so compute smooth vertex normals.
  for(let i=0;i<indices.length;i+=3){
   const ai=indices[i]*3,bi=indices[i+1]*3,ci=indices[i+2]*3;
   const ux=positions[bi]-positions[ai],uy=positions[bi+1]-positions[ai+1],uz=positions[bi+2]-positions[ai+2];
   const vx=positions[ci]-positions[ai],vy=positions[ci+1]-positions[ai+1],vz=positions[ci+2]-positions[ai+2];
   const nx=uy*vz-uz*vy,ny=uz*vx-ux*vz,nz=ux*vy-uy*vx;
   for(const j of [ai,bi,ci]){normals[j]+=nx;normals[j+1]+=ny;normals[j+2]+=nz;}
  }
  for(let j=0;j<positions.length;j+=3){
   const m=Math.hypot(normals[j],normals[j+1],normals[j+2])||1;
   normals[j]/=m;normals[j+1]/=m;normals[j+2]/=m;
   for(let k=0;k<3;k++){globalBounds.min[k]=Math.min(globalBounds.min[k],positions[j+k]);globalBounds.max[k]=Math.max(globalBounds.max[k],positions[j+k]);}
  }
  const arr=new Float32Array(positions.length*2);
  for(let j=0;j<positions.length/3;j++){
   const p=j*3,o=j*6;
   arr[o]=positions[p];arr[o+1]=positions[p+1];arr[o+2]=positions[p+2];
   arr[o+3]=normals[p];arr[o+4]=normals[p+1];arr[o+5]=normals[p+2];
  }
  const vao=gl.createVertexArray();gl.bindVertexArray(vao);
  const vbo=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,vbo);gl.bufferData(gl.ARRAY_BUFFER,arr,gl.STATIC_DRAW);
  gl.enableVertexAttribArray(0);gl.vertexAttribPointer(0,3,gl.FLOAT,false,24,0);
  gl.enableVertexAttribArray(1);gl.vertexAttribPointer(1,3,gl.FLOAT,false,24,12);
  const ebo=gl.createBuffer();gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER,ebo);gl.bufferData(gl.ELEMENT_ARRAY_BUFFER,indices,gl.STATIC_DRAW);
  const material=model.materials?.[prim.material||0]?.pbrMetallicRoughness||{};
  models.push({vao,amount:indices.length,indexType:indices instanceof Uint16Array?gl.UNSIGNED_SHORT:gl.UNSIGNED_INT,base:material.baseColorFactor?.slice(0,3)||[.55,.35,.15],rough:material.roughnessFactor??.35});
 }}
 gl.bindVertexArray(null);
 if(!models.length)throw Error('No model geometry');
}catch(e){fallback(e.message);return;}
const loc={};for(const k of ['uAngle','uCameraDistance','uCenterY','uAspect','uFocal','uBase','uRoughness'])loc[k]=gl.getUniformLocation(program,k);
gl.enable(gl.DEPTH_TEST);gl.depthFunc(gl.LEQUAL);gl.disable(gl.CULL_FACE);gl.clearColor(0,0,0,0);
const min=globalBounds.min,max=globalBounds.max;
const yCenter=(min[1]+max[1])*.5;
const halfY=(max[1]-min[1])*.5;
const halfX=Math.max(Math.abs(min[0]),Math.abs(max[0]));
const halfZ=Math.max(Math.abs(min[2]),Math.abs(max[2]));
const sweepRadius=Math.hypot(halfX,halfZ);
let angle=0,angularSpeed=Math.PI*2/28,spinning=true,paused=false,dragging=false,visible=true,last=0,raf=0,pointerX=0;
let canvasW=0,canvasH=0,fitAspect=0,fitDistance=0;
function computeFit(aspect,focal){
 // Fit ACTUAL rotated vertices at 36 points around the axis. This gives a
 // tighter, safe fit than a bounding sphere and includes both head + pedestal.
 const fill=.92;let d=0;
 for(let sample=0;sample<36;sample++){
  const a=sample*Math.PI*2/36,c=Math.cos(a),s=Math.sin(a);
  for(const ps of positionArrays){
   for(let i=0;i<ps.length;i+=3){
    const x=ps[i],y=ps[i+1],z=ps[i+2];
    const xx=c*x+s*z,zz=-s*x+c*z;
    const candidate=Math.max(zz+Math.abs(y-yCenter)*focal/fill,
                             zz+Math.abs(xx)*focal/(aspect*fill));
    if(candidate>d)d=candidate;
   }
  }
 }
 return d+.22;
}
function render(){
 const rect=canvas.getBoundingClientRect();
 const dpr=Math.min(window.devicePixelRatio||1,1.5);
 const w=Math.round(rect.width*dpr),h=Math.round(rect.height*dpr);
 if(w<2||h<2)return false;
 if(w!==canvasW||h!==canvasH){canvasW=w;canvasH=h;canvas.width=w;canvas.height=h;gl.viewport(0,0,w,h);}
 const aspect=w/h,focal=1.90;
 if(Math.abs(aspect-fitAspect)>.0002){fitAspect=aspect;fitDistance=computeFit(aspect,focal);}
 const distance=fitDistance;
 gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);gl.useProgram(program);
 gl.uniform1f(loc.uAngle,angle);
 gl.uniform1f(loc.uCenterY,yCenter);gl.uniform1f(loc.uCameraDistance,distance);
 gl.uniform1f(loc.uAspect,aspect);gl.uniform1f(loc.uFocal,focal);
 for(const mesh of models){
  gl.uniform3fv(loc.uBase,mesh.base);gl.uniform1f(loc.uRoughness,mesh.rough);
  gl.bindVertexArray(mesh.vao);gl.drawElements(gl.TRIANGLES,mesh.amount,mesh.indexType,0);
 }
 gl.bindVertexArray(null);return true;
}
function tick(now){raf=0;const dt=Math.min(.05,last?(now-last)/1000:0);last=now;
 if(!paused&&spinning&&!dragging&&!document.hidden&&visible)angle=(angle+dt*angularSpeed)%(Math.PI*2);
 if(visible&&!document.hidden)render();
 if(!document.hidden&&(spinning&&!paused||dragging))raf=requestAnimationFrame(tick);
}
function schedule(){if(!raf)raf=requestAnimationFrame(tick);}
function updateButton(){if(!toggle)return;toggle.disabled=false;toggle.hidden=false;
 toggle.textContent=spinning?'Остановить вращение':'Включить вращение';toggle.setAttribute('aria-pressed',String(spinning));}
// First draw before crossfading poster -> 3D to avoid sudden empty frame.
try{if(!render())throw Error('Canvas area is not ready');
 stage.classList.add('webgl-hero');stage.dataset.webgl='ready';
 if(loading)loading.hidden=true;updateButton();schedule();
}catch(e){fallback(e.message);return;}
toggle?.addEventListener('click',()=>{spinning=!spinning;updateButton();schedule();});
canvas.addEventListener('pointerdown',e=>{dragging=true;pointerX=e.clientX;canvas.setPointerCapture(e.pointerId);schedule();});
canvas.addEventListener('pointermove',e=>{if(!dragging)return;angle+=(e.clientX-pointerX)*.012;pointerX=e.clientX;render();});
function release(){dragging=false;schedule();}
canvas.addEventListener('pointerup',release);canvas.addEventListener('pointercancel',release);
canvas.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){
 e.preventDefault();angle+=(e.key==='ArrowLeft'?-1:1)*.19;render();schedule();}
 else if(e.key===' '||e.key==='Enter'){e.preventDefault();spinning=!spinning;updateButton();schedule();}});
addEventListener('sandow:motion',e=>{paused=!!e.detail.paused;schedule();});
addEventListener('resize',schedule,{passive:true});
if('ResizeObserver'in window)new ResizeObserver(schedule).observe(canvas);
if('IntersectionObserver'in window)new IntersectionObserver(entries=>{visible=!!entries[0]?.isIntersecting;if(visible)schedule();},{threshold:0}).observe(stage);
canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();cancelAnimationFrame(raf);raf=0;fallback('WebGL context lost');});
canvas.addEventListener('webglcontextrestored',()=>location.reload());
addEventListener('visibilitychange',()=>{last=0;if(!document.hidden)schedule();});
})();
